FORTSCHRITT: async (r, T, arg, HILF) => {
    const { s, L } = HILF;
    if (!L.length) return { fehler: "keine Bewohner am Messort" };
    const wm = s.worldMeta;
    if (!wm) return { fehler: "kein worldMeta: die Welt trägt keinen Kalender" };
